-- Household-to-building links derived from the Trung Chanh 2 hamlet drawing (tc2-drawing-20261108).
-- Generated data: stable household codes, building IDs and public footprint geometry only.
-- Safe on any environment: unknown households are skipped; a household that already has a link keeps it.
CREATE TABLE public.gis_field_building_household_import (
    source varchar(64) NOT NULL,
    household_code varchar(255) NOT NULL,
    household_id bigint NOT NULL REFERENCES public.household(id) ON DELETE CASCADE,
    building_id varchar(120) NOT NULL,
    match_tier varchar(16) NOT NULL CHECK (match_tier IN ('exact','hamlet','base')),
    building_created boolean NOT NULL,
    created_feature_md5 text,
    applied_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source, household_code)
);
COMMENT ON TABLE public.gis_field_building_household_import IS 'Provenance of bulk household links; the drawing is hand-made, so these are unverified until an officer confirms them';

CREATE TEMP TABLE stage_tc2_building (building_id varchar(120) PRIMARY KEY, feature_json text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE stage_tc2_link (household_code varchar(255) PRIMARY KEY, building_id varchar(120) NOT NULL, match_tier varchar(16) NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE resolved_tc2_link ON COMMIT DROP AS
SELECT l.household_code, h.id AS household_id, l.building_id, l.match_tier,
       NOT EXISTS (SELECT 1 FROM public.gis_field_building b WHERE b.id = l.building_id) AS building_created
FROM stage_tc2_link l
JOIN public.household h ON h.code = l.household_code
WHERE NOT EXISTS (SELECT 1 FROM public.gis_field_building_household x WHERE x.household_id = h.id);

SELECT DISTINCT s.building_id, s.feature_json
FROM stage_tc2_building s JOIN resolved_tc2_link r ON r.building_id = s.building_id AND r.building_created;

UPDATE public.gis_field_building b
SET feature_json = jsonb_set(b.feature_json::jsonb, '{properties,householdIds}',
    coalesce(b.feature_json::jsonb #> '{properties,householdIds}', '[]'::jsonb) || a.ids, true)::text
FROM (SELECT building_id, jsonb_agg(household_id::text ORDER BY household_id) AS ids FROM resolved_tc2_link GROUP BY building_id) a
WHERE b.id = a.building_id;

SELECT 'tc2-drawing-20261108', r.household_code, r.household_id, r.building_id, r.match_tier, r.building_created,
       CASE WHEN r.building_created THEN md5((b.feature_json::jsonb #- '{properties,householdIds}')::text) END
FROM resolved_tc2_link r JOIN public.gis_field_building b ON b.id = r.building_id;
